fn sum(n int) int {if n==0{return 0}
return n+sum(n-1)}
fn main(){const k=3
var v=sum(k)
{let t=1
v+=t}
print(v)}

fn ready() Result<void>{return ok()}
fn main(){let r=ready()
unwrap(r)
print(r,is_ok(r))}

import std.error as e
let x=e.from_string("old", "origin")
let y=unwrap(e.wrap("app","load","failed",x))
print(e.code(y),e.code(unwrap(e.cause(y))))

interface Named{fn name() string}
struct Item{value string}
fn Item.name() string{return self.value}
fn show(x Named) string{return x.name()}
print(show(Item{value:"Hua"}))

enum Event{Number(int),Empty}
fn show(x Event) int{match x{Number(n)=>{return n}
Empty=>{return 0}}}
print(show(Event.Number(4)))

fn id<T>(x T) T{return x}
struct Box<T>{value T}
print(id<int>(Box<int>{value:5}.value))

