fn f() int{defer print("clean")
return 3}
fn main(){print(f())}

async fn work(x int) int{return x*2}
fn main(){let t=work(3)
print(await t,await t)}

async fn work() int{defer print("done")
return 1}
fn main(){taskgroup{spawn work()}
print("after")}

