simd for i in 0..3 {out[i]=out[i]*2.0}
print(out)}

import std.bytes as b
let x=unwrap(b.u32_le(16909060))
print(unwrap(b.to_ints(x)),unwrap(b.read_u32_le(x,0)),b.crc32(b.from_text("123456789")))

import std.buffer as b
var x=b.new()
print(unwrap(b.write_text(x,"Hua")),unwrap(b.text(x)))

